def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    sys.setrecursionlimit(max(sys.getrecursionlimit(), 1_000_000))

    token_re = re.compile(r"\s*(<=|>=|<>|[A-Z]+[0-9]*|[0-9]+|[+\-*/(),:=<>])")
    values = {}
    active = set()

    def parse(text):
        tokens = token_re.findall(text)
        pos = 0

        def expression():
            nonlocal pos
            node = term()
            while pos < len(tokens) and tokens[pos] in ("+", "-"):
                op = tokens[pos]
                pos += 1
                node = (op, node, term())
            return node

        def term():
            nonlocal pos
            node = unary()
            while pos < len(tokens) and tokens[pos] in ("*", "/"):
                op = tokens[pos]
                pos += 1
                node = (op, node, unary())
            return node

        def unary():
            nonlocal pos
            count = 0
            while pos < len(tokens) and tokens[pos] == "-":
                count += 1
                pos += 1
            node = atom()
            if count % 2:
                node = ("neg", node)
            return node

        def atom():
            nonlocal pos
            token = tokens[pos]
            pos += 1

            if token.isdigit():
                return ("number", int(token))

            if token == "(":
                node = expression()
                pos += 1  # )
                return node

            if token == "IF":
                pos += 1  # (
                left = expression()
                op = tokens[pos]
                pos += 1
                right = expression()
                pos += 1  # ,
                then = expression()
                pos += 1  # ,
                otherwise = expression()
                pos += 1  # )
                return ("if", op, left, right, then, otherwise)

            if token in ("SUM", "MIN", "MAX"):
                pos += 1  # (
                args = []
                while True:
                    if (
                        pos + 1 < len(tokens)
                        and tokens[pos][0].isalpha()
                        and tokens[pos][-1].isdigit()
                        and tokens[pos + 1] == ":"
                    ):
                        args.append(("range", tokens[pos], tokens[pos + 2]))
                        pos += 3
                    else:
                        args.append(expression())
                    if tokens[pos] == ")":
                        pos += 1
                        break
                    pos += 1  # ,
                return ("function", token, args)

            return ("cell", token)

        return expression()

    def is_error(value):
        return isinstance(value, str)

    def get_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return "#CYCLE!"

        active.add(name)
        content = cells[name]
        if content.startswith("="):
            value = evaluate(parse(content[1:]))
        else:
            value = int(content)
        active.remove(name)
        values[name] = value
        return value

    def evaluate(node):
        kind = node[0]

        if kind == "number":
            return node[1]
        if kind == "cell":
            return get_cell(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if is_error(value) else -value

        if kind in ("+", "-", "*", "/"):
            left = evaluate(node[1])
            if is_error(left):
                return left
            right = evaluate(node[2])
            if is_error(right):
                return right
            if kind == "+":
                return left + right
            if kind == "-":
                return left - right
            if kind == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "if":
            left = evaluate(node[2])
            if is_error(left):
                return left
            right = evaluate(node[3])
            if is_error(right):
                return right
            op = node[1]
            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(node[4] if condition else node[5])

        function = node[1]
        result = None
        for arg in node[2]:
            if arg[0] == "range":
                first, last = arg[1], arg[2]
                col1, col2 = sorted((ord(first[0]), ord(last[0])))
                row1, row2 = sorted((int(first[1:]), int(last[1:])))
                names = (
                    chr(col) + str(row)
                    for row in range(row1, row2 + 1)
                    for col in range(col1, col2 + 1)
                )
                for name in names:
                    if name not in cells:
                        continue
                    value = get_cell(name)
                    if is_error(value):
                        return value
                    if result is None:
                        result = value
                    elif function == "SUM":
                        result += value
                    elif function == "MIN":
                        result = min(result, value)
                    else:
                        result = max(result, value)
            else:
                value = evaluate(arg)
                if is_error(value):
                    return value
                if result is None:
                    result = value
                elif function == "SUM":
                    result += value
                elif function == "MIN":
                    result = min(result, value)
                else:
                    result = max(result, value)

        return 0 if result is None else result

    for name in cells:
        get_cell(name)

    return {name: values[name] for name in cells}
